package Lamda_expression;public interface Calculator {    int calculate(int a,int b);}class details {    public static void main(String[] args)    {        Calculator mul=(a,b)->{            return a*b;        };        Calculator divide=(a,b)->{            return a/b;        };        Calculator plus=(a,b)->{            return a+b;        };        Calculator substration=(a,b)->{            return a-b;        };        System.out.println("MULTIPLICATION "+mul.calculate(10,20));        System.out.println("Division "+divide.calculate(20,20));        System.out.println("Addition "+plus.calculate(10,20));        System.out.println("Substration " +substration.calculate(10,20));    }}